package com.travbook.stays.application.usecase;
import com.travbook.stays.application.port.in.HotelStays;
import com.travbook.stays.application.port.out.*;
import com.travbook.stays.domain.model.Stay.*;
import com.travbook.shared.domain.*;
import com.travbook.customer.application.port.in.Customers;
import java.time.*;
import java.util.*;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
public final class StayService implements HotelStays {
 private final Customers customers;private final StaySelection selection;private final StayStore store;private final Clock clock;
 public StayService(Customers customers,StaySelection selection,StayStore store,Clock clock){this.customers=customers;this.selection=selection;this.store=store;this.clock=clock;}
 private UUID owner(CustomerIdentity identity){return customers.resolve(identity).id();}
 private void key(String key){if(key==null||!key.matches("[A-Za-z0-9_-]{16,100}"))throw new DomainFailure(DomainFailure.Code.VALIDATION_FAILED,"Provide an Idempotency-Key of 16–100 letters, digits, hyphens or underscores.");}
 private void consent(boolean value){if(!value)throw new DomainFailure(DomainFailure.Code.VALIDATION_FAILED,"Explicit consent is required.");}
 private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 public QuoteDetails quote(CustomerIdentity identity,List<UUID> ids,String key,UUID correlation){return quote(identity,ids,CollectionMethod.PAY_NOW,key,correlation);}
 public QuoteDetails quote(CustomerIdentity identity,List<UUID> ids,CollectionMethod method,String key,UUID correlation){Objects.requireNonNull(method);key(key);if(ids==null||ids.isEmpty()||ids.size()>4||ids.stream().anyMatch(Objects::isNull))throw new DomainFailure(DomainFailure.Code.VALIDATION_FAILED,"Select one offer per room.");UUID owner=owner(identity);String fingerprint=hash(ids.toString()+(method==CollectionMethod.PAY_NOW?"":":"+method));var replay=store.replay(owner,"QUOTE",key,fingerprint);if(replay.isPresent())return store.quote(owner,replay.get());var chosen=selection.reprice(ids,method);Instant now=clock.instant(),expiry=chosen.expiresAt();Instant checkIn=chosen.criteria().checkIn().atTime(LocalTime.parse(chosen.property().checkInTime())).atZone(ZoneId.of(chosen.property().timezone())).toInstant();if(checkIn.isBefore(expiry))expiry=checkIn;if(!expiry.isAfter(now))throw new DomainFailure(DomainFailure.Code.QUOTE_EXPIRED,"Hotel rate check expired.");var q=new Quote(UUID.randomUUID(),owner,1,chosen,now,expiry);q.valid(now);q=store.createQuote(q,key,fingerprint,correlation);return store.quote(owner,q.id());}
 public QuoteDetails getQuote(CustomerIdentity identity,UUID id){return store.quote(owner(identity),id);}
 public QuoteDetails accept(CustomerIdentity identity,UUID id,int version,boolean consent,String key,UUID correlation){consent(consent);key(key);UUID owner=owner(identity);store.accept(owner,id,version,key,hash(id+":"+version),correlation);return store.quote(owner,id);}
 public Booking book(CustomerIdentity identity,UUID quoteId,int version,List<Guest> guests,SpecialRequest request,Scenario scenario,boolean consent,String key,UUID correlation){consent(consent);key(key);if(request==null||scenario==null)throw new DomainFailure(DomainFailure.Code.VALIDATION_FAILED,"Select the request and demonstration outcome.");return store.createBooking(owner(identity),quoteId,version,guests,request,scenario,key,hash(quoteId+":"+version+":"+guests+":"+request+":"+scenario),correlation);}
 public Booking amend(CustomerIdentity identity,UUID id,UUID quoteId,long version,boolean consent,boolean loss,String key,UUID correlation){consent(consent);key(key);return store.amend(owner(identity),id,quoteId,version,loss,key,hash(id+":"+quoteId+":"+version+":"+loss),correlation);}
 public ChangeQuote changeQuote(CustomerIdentity identity,UUID booking,long version,com.travbook.hotels.domain.model.HotelCriteria criteria,List<com.travbook.hotels.domain.model.HotelOffer.Plan> plans,String key,UUID correlation){key(key);UUID owner=owner(identity);String fingerprint=hash("CHANGE_QUOTE:"+booking+":"+version+":"+criteria+":"+plans);var replay=store.replay(owner,"QUOTE",key,fingerprint);if(replay.isPresent())return store.changeQuote(owner,booking,replay.get());var b=store.booking(owner,booking);b.changeAllowed(version,clock.instant());if(plans==null||plans.size()!=criteria.rooms().size()||plans.stream().anyMatch(Objects::isNull))throw new DomainFailure(DomainFailure.Code.VALIDATION_FAILED,"Choose one replacement plan for each room.");var selected=selection.change(b,criteria,plans);Instant expiry=selected.expiresAt();if(b.currentQuote().checkIn().isBefore(expiry))expiry=b.currentQuote().checkIn();if(!b.deferred())for(var offer:b.currentQuote().selection().offers())if(offer.freeCancellationUntil().isBefore(expiry))expiry=offer.freeCancellationUntil();var q=new Quote(UUID.randomUUID(),owner,1,selected,clock.instant(),expiry);return store.createChangeQuote(owner,booking,version,q,key,fingerprint,correlation);}
 public Booking change(CustomerIdentity identity,UUID booking,UUID quote,long version,List<Guest> guests,Scenario scenario,boolean consent,boolean delay,boolean loss,String key,UUID correlation){consent(consent);key(key);Objects.requireNonNull(scenario);return store.change(owner(identity),booking,quote,version,guests,scenario,delay,loss,key,hash(booking+":"+quote+":"+version+":"+guests+":"+scenario+":"+delay+":"+loss),correlation);}
 public Booking get(CustomerIdentity identity,UUID id){return store.booking(owner(identity),id);}
 public Page list(CustomerIdentity identity,UUID after){return store.list(owner(identity),after);}
 public CancellationQuote cancellationQuote(CustomerIdentity identity,UUID id,String key,UUID correlation){key(key);return store.cancellationQuote(owner(identity),id,key,correlation);}
 public Booking cancel(CustomerIdentity identity,UUID id,UUID quoteId,boolean consent,boolean delay,boolean loss,String key,UUID correlation){consent(consent);key(key);return store.cancel(owner(identity),id,quoteId,delay,loss,key,hash(id+":"+quoteId+":"+delay+":"+loss),correlation);}
 public Voucher voucher(CustomerIdentity identity,UUID id,String key,UUID correlation){key(key);return store.voucher(owner(identity),id,key,correlation);}
 public Voucher readVoucher(CustomerIdentity identity,UUID id){var v=store.readVoucher(owner(identity),id);if(v.content().getBytes(StandardCharsets.UTF_8).length!=v.byteLength()||!hash(v.content()).equals(v.sha256()))throw new IllegalStateException("Hotel voucher integrity check failed");return v;}
 public List<Event> timeline(CustomerIdentity identity,UUID id){return store.timeline(owner(identity),id);}
}
